<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Basic Auth Header Generator','description'=>'Generate a Base64 HTTP Basic Authentication value locally from a username and password.','url'=>'https://smarttoolz.in/tools/basic-auth-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool"><h1>Basic Auth Header Generator</h1><p>Create an HTTP Basic Authorization value locally.</p><input id="u" placeholder="Username"><input id="p" type="password" placeholder="Password"><button id="go">Generate</button><div id="o"></div></main><style>.tool{max-width:760px;margin:60px auto;padding:24px}.tool input{display:block;width:100%;box-sizing:border-box;margin:8px 0;padding:13px;border:1px solid #ddd;border-radius:10px}.tool button{padding:12px 18px;border:0;border-radius:10px;background:#5541ff;color:#fff;font-weight:800}.tool #o{margin-top:16px;padding:14px;background:#f6f7fb;border-radius:10px;word-break:break-all}</style><script>go.onclick=()=>o.textContent='Authorization: Basic '+btoa(unescape(encodeURIComponent(u.value+':'+p.value)))</script><?php smarttoolz_tool_page_end(); ?>